INSERT INTO feat VALUES (98,'Improved Favored Enemy','Epic','Yes','Yes',NULL,'Five or more favored enemies.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Add +1 to the bonus on Bluff, Listen, Sense Motive, Spot, and Survival checks and damage rolls against all the character\'s favored enemies.</p>\n</div>\n',NULL,'This feat may be taken multiple times. Its effects stack.','\n      <div topic=\"Improved Favored Enemy\" level=\"3\"><p><h3>Improved Favored Enemy [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Five or more favored enemies.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Add +1 to the bonus on Bluff, Listen, Sense Motive, Spot, and Survival checks and damage rolls against all the character\'s favored enemies.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> This feat may be taken multiple times. Its effects stack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (99,'Improved Heighten Spell','Epic','No','No',NULL,'Heighten Spell, Spellcraft 20 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> As Heighten Spell, but there is no limit to the level to which the character can heighten the spell.</p>\n</div>\n','Without this feat, a spell can only be heightened to a maximum of 9th level.',NULL,'\n      <div topic=\"Improved Heighten Spell\" level=\"3\"><p><h3>Improved Heighten Spell [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Heighten Spell, Spellcraft 20 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> As Heighten Spell, but there is no limit to the level to which the character can heighten the spell.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, a spell can only be heightened to a maximum of 9th level.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (100,'Improved Ki Strike','Epic','No','No',NULL,'Wis 21, ki strike (adamantine).','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character\'s unarmed strikes are treated as epic magic weapons for the purposes of damage reduction.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Improved Ki Strike\" level=\"3\"><p><h3>Improved Ki Strike [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Wis 21, <i>ki</i> strike (adamantine).</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character\'s unarmed strikes are treated as epic magic weapons for the purposes of damage reduction.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (101,'Improved Low-Light Vision','Epic','Yes','Yes',NULL,'Low-light vision.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The range of the character\'s low-light vision doubles. This feat does not stack with low-light vision granted by magic items or nonpermanent magical effects.</p>\n</div>\n',NULL,'This feat may be taken multiple times. Its effects stack. Remember that two doublings equals a tripling, and so on.','\n      <div topic=\"Improved Low-Light Vision\" level=\"3\"><p><h3>Improved Low-Light Vision [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Low-light vision.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The range of the character\'s low-light vision doubles. This feat does not stack with low-light vision granted by magic items or nonpermanent magical effects.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> This feat may be taken multiple times. Its effects stack. Remember that two doublings equals a tripling, and so on.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (102,'Improved Manifestation','Epic, Psionic','Yes','Yes',NULL,'Character level 21st, ability to manifest powers of the normal maximum power level in at least one psionic class.','<p>You increase your power point reserve.</p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When you select this feat, you gain 19 power points.</p>\n</div>\n',NULL,'You can gain this feat multiple times. Each time you do so, you gain an additional number of power points equal to your previous benefit +2.','\n      <div topic=\"Improved Manifestation\" level=\"3\"><p><h3>Improved Manifestation [Epic, Psionic]</h3></p><p>You increase your power point reserve.</p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Character level 21st, ability to manifest powers of the normal maximum power level in at least one psionic class.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When you select this feat, you gain 19 power points.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can gain this feat multiple times. Each time you do so, you gain an additional number of power points equal to your previous benefit +2.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (103,'Improved Manyshot','Epic','No','No',NULL,'Dex 19, base attack bonus +21, Many-shot, Point Blank Shot, Rapid Shot','<div topic=\"Benefits\" level=\"8\"><p><b>Benefits:</b> As Manyshot, but the number of arrows the character can fire is limited only by his or her base attack bonus (two arrows, plus one arrow for every 5 points of base attack bonus above +6).</p>\n</div>\n','With the Manyshot feat, the character is limited to a maximum of four arrows fired (when the character\'s base attack bonus is +16 or higher).','Regardless of the number of arrows the character fires, he or she only applies precision-based damage (such as sneak attack damage or the ranger\'s favored enemy bonus) once. If the character scores a critical hit, only one of the arrows deals critical damage (character\'s choice); all others deal normal damage.','\n      <div topic=\"Improved Manyshot\" level=\"3\"><p><h3>Improved Manyshot [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Dex 19, base attack bonus +21, Many-shot, Point Blank Shot, Rapid Shot</p>\n</div><div topic=\"Benefits\" level=\"8\"><p><b>Benefits:</b> As Manyshot, but the number of arrows the character can fire is limited only by his or her base attack bonus (two arrows, plus one arrow for every 5 points of base attack bonus above +6).</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> Regardless of the number of arrows the character fires, he or she only applies precision-based damage (such as sneak attack damage or the ranger\'s favored enemy bonus) once. If the character scores a critical hit, only one of the arrows deals critical damage (character\'s choice); all others deal normal damage.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> With the Manyshot feat, the character is limited to a maximum of four arrows fired (when the character\'s base attack bonus is +16 or higher).</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (104,'Improved Metamagic','Epic','Yes','Yes',NULL,'Four metamagic feats, Spellcraft 30 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The spell slot modifier of all the character\'s metamagic feats is reduced by one level, to a minimum of +1. This feat has no effect on metamagic feats whose spell slot modifier is +1 or less.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. The effects stack, though a character can\'t reduce any metamagic feat\'s spell slot modifier to less than +1.','\n      <div topic=\"Improved Metamagic\" level=\"3\"><p><h3>Improved Metamagic [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Four metamagic feats, Spellcraft 30 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The spell slot modifier of all the character\'s metamagic feats is reduced by one level, to a minimum of +1. This feat has no effect on metamagic feats whose spell slot modifier is +1 or less.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. The effects stack, though a character can\'t reduce any metamagic feat\'s spell slot modifier to less than +1.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (105,'Improved Metapsionics','Epic, Psionic','Yes','Yes',NULL,'Character level 21st, four metapsionic feats, Psicraft 30 ranks.','<p>You can manifest powers using metapsionic feats more easily than normal.</p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Metapsionic powers you manifest cost 2 power points less than normal (to a minimum of 1 power point).</p><p>This feat has no effect on metapsionic powers that inflate the cost by only 2 power points.</p>\n</div>\n',NULL,'You can gain this feat multiple times. The effects stack, though you can\'t lower the cost of any metapsionic power to less than 1 power point.','\n      <div topic=\"Improved Metapsionics\" level=\"3\"><p><h3>Improved Metapsionics [Epic, Psionic]</h3></p><p>You can manifest powers using metapsionic feats more easily than normal.</p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Character level 21st, four metapsionic feats, Psicraft 30 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Metapsionic powers you manifest cost 2 power points less than normal (to a minimum of 1 power point).</p><p>This feat has no effect on metapsionic powers that inflate the cost by only 2 power points.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can gain this feat multiple times. The effects stack, though you can\'t lower the cost of any metapsionic power to less than 1 power point.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (106,'Improved Sneak Attack','Epic','Yes','Yes',NULL,'Sneak attack +8d6.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Add +1d6 to the character\'s sneak attack damage.</p>\n</div>\n',NULL,'This feat may be taken multiple times. Its effects stack.','\n      <div topic=\"Improved Sneak Attack\" level=\"3\"><p><h3>Improved Sneak Attack [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Sneak attack +8d6.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Add +1d6 to the character\'s sneak attack damage.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> This feat may be taken multiple times. Its effects stack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (107,'Improved Spell Capacity','Epic','Yes','Yes','One spell slot per day of any level up to one level higher than the highest-level spell the character can already cast in a particular class','Ability to cast spells of the normal maximum spell level in at least one spellcasting class.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When the character selects this feat, he or she gains one spell slot per day of any level up to one level higher than the highest-level spell the character can already cast in a particular class. The character must still have the requisite ability score (10 + spell level) in order to cast any spell stored in this slot. If the character has a high enough ability modifier to gain one or more bonus spells for this spell level, he or she also gains the bonus spells for this spell level. The character must use the spell slot as a member of the class in which he or she can already cast spells of the normal maximum spell level.</p>\n</div><div topic=\"Spell Slots Above 9th Level\" level=\"5\"><p><h5><b>Spell Slots Above 9th Level</b> </h5></p><p>The Improved Spell Capacity feat allows characters to gain spell slots above 9th level (which can be used to hold lower-level spells or spells whose level has been increased beyond 9th by the use of metamagic feats).</p><p>A character with a very high score in the ability associated with his or her spellcasting (Intelligence for wizards; Wisdom for clerics, druids, paladins, and rangers; or Charisma for bards and sorcerers) may receive bonus spells of those levels, as shown on Table: Expanded Ability Modifiers and Bonus Spells, but only if they already have at least one spell slot of that level (such as from the Improved Spell Capacity feat). A character without any spell slots of a level can\'t receive any bonus spells of that level, even if the appropriate ability score is high enough to award them.</p><p>Even though the table only includes ability scores up to 61 and spell slots up to 25th level, the progression continues infinitely in both directions. For ability scores beyond 61, or for spell slots above 25th level, expand the table to follow the same patterns as shown.</p><p/><p><b>Table: Expanded Ability Modifiers and Bonus Spells</b></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"19\" curcol=\"3\">\n<td/>\n<td colspan=\"17\" align=\"center\"><b>--------------- Spells per Day -------------------</b><br/></td> \n</tr>\n\n<tr maxcol=\"19\" curcol=\"19\">\n<td><b>Score</b><br/></td>\n<td><b>Modifier</b><br/></td>\n<td><b>10th</b><br/></td>\n<td><b>11th</b><br/></td>\n<td><b>12th</b><br/></td>\n<td><b>13th</b><br/></td>\n<td><b>14th</b><br/></td>\n<td><b>15th</b><br/></td>\n<td><b>16th</b><br/></td>\n<td><b>17th</b><br/></td>\n<td><b>18th</b><br/></td>\n<td><b>19th</b><br/></td>\n<td><b>20th</b><br/></td>\n<td><b>21st</b><br/></td>\n<td><b>22nd</b><br/></td>\n<td><b>23rd</b><br/></td>\n<td><b>24th</b><br/></td>\n<td><b>25th</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"19\" curcol=\"19\">\n<td>10-11<br/></td>\n<td>+0<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"19\" curcol=\"19\">\n<td>12-13<br/></td>\n<td>+1<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"19\" curcol=\"19\">\n<td>14-15<br/></td>\n<td>+2<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br